async function assembleText(
    stream: AsyncIterable&lt;TextContentChunk&gt;
): Promise&lt;TextContent&gt; {
    const chunks: TextContentChunk[] = [];
    let fullText = "";
    for await (const chunk of stream) {
        chunks.push(chunk);
        fullText += chunk.text;
    }
    return new TextContent({
        text: fullText,
        _chunks: chunks
    });
}
